makeMtLab(document.getElementById("lab-l18"),{id:"l18",scenarios:[{"label": "Ví dụ: Ba tầng của hạt điều", "note": "Từ nhóm chung tới lượng thật.", "steps": [{"t": "Lớp", "html": "<p class=\"mt-calc\">W320 rang muối<\/p>"}, {"t": "Hai định nghĩa", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Mã<\/th><th scope=\"col\">NCC<\/th><\/tr><\/thead><tbody><tr><td>HD-W320-RM-NCC-A<\/td><td>A<\/td><\/tr><tr><td>HD-W320-RM-NCC-B<\/td><td>B<\/td><\/tr><\/tbody><\/table>"}, {"t": "Lô", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Lô<\/th><th scope=\"col\">Mã<\/th><th scope=\"col\">Kg<\/th><th scope=\"col\">Hạn<\/th><\/tr><\/thead><tbody><tr><td>LOT-1108<\/td><td>…NCC-A<\/td><td>1 000<\/td><td>08/05/2027<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "“Hạn dùng 08/05/2027” đặt ở tầng nào?", "o": ["Lớp", "Định nghĩa", "Lô"], "a": 2}}]}, {"label": "Ví dụ: Thay nhà cung cấp", "note": "BOM trỏ tới lớp.", "steps": [{"t": "BOM: 0,500 kg lớp W320 rang muối", "html": "<p class=\"mt-calc\">Không ghi mã NCC<\/p>"}, {"t": "Nạp lô của NCC-B", "html": "<p class=\"mt-calc\">NCC-B thuộc lớp → MES chấp nhận<\/p>", "ask": {"q": "Có phải sửa BOM không?", "o": ["Có", "Không"], "a": 1}}]}, {"label": "Ví dụ: Lô bị giữ", "note": "Trạng thái là thuộc tính của lô.", "steps": [{"t": "LOT-1112 độ ẩm cao", "html": "<p class=\"mt-calc\">QC đặt status = HOLD<\/p>"}, {"t": "Quét lô khi nạp", "html": "<p class=\"mt-calc\">MES từ chối: lô đang giữ<\/p>", "say": "<p>Chương 16 dùng trạng thái này để chống nạp sai.<\/p>"}]}, {"label": "Bẫy: Hạn dùng ở tầng định nghĩa", "note": "Mọi lô dùng chung một hạn.", "steps": [{"t": "Định nghĩa ghi hạn 08/05/2027", "html": "<p class=\"mt-calc\">Lô nhập sau có hạn khác<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Hạn là cột của bảng lô<\/p>"}]}, {"label": "Lỗi: BOM trỏ mã cụ thể", "note": "Đổi nhà cung cấp là phải sửa BOM.", "steps": [{"t": "BOM ghi HD-W320-RM-NCC-A", "html": "<p class=\"mt-calc\">Kho chỉ còn hàng NCC-B<\/p>"}, {"t": "MES chặn nạp", "html": "<p class=\"mt-calc\">Dây chuyền dừng vì “sai vật tư”<\/p>", "say": "<p>Trỏ tới lớp khi các mã thay thế được cho nhau.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l18"),"l18",[{"kind": "num", "t": "Lô vật tư", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Lô 1 000 kg, đã xuất 120 kg và 250 kg. Còn bao nhiêu kg?", "a": 630, "unit": "kg"}, {"q": "Lớp có 3 nhà cung cấp, mỗi nhà 2 mã. Bao nhiêu định nghĩa?", "a": 6, "unit": "mã"}, {"q": "Mỗi hộp 0,500 kg. 630 kg đủ cho bao nhiêu hộp?", "a": 1260, "unit": "hộp"}], "hints": ["Còn lại = lô − các lần xuất.", "Số hộp = kg / 0,5."], "why": "1 000 − 370 = 630; 3 × 2 = 6; 630 / 0,5 = 1 260."}, {"kind": "pick", "t": "Tầng nào?", "d": "<p>Thuộc tính này đặt ở tầng nào?<\/p>", "cats": ["Lớp", "Định nghĩa", "Lô"], "items": [{"q": "Hạn dùng", "a": 2}, {"q": "Đơn vị tính kg", "a": 1}, {"q": "Nhóm thay thế được", "a": 0}, {"q": "Độ ẩm đo khi nhập", "a": 2}, {"q": "Nhà cung cấp", "a": 1}], "hints": ["Riêng từng lượng thật: lô.", "Chung cho mã: định nghĩa; chung cho nhóm: lớp."], "why": "Hạn, độ ẩm: lô; đơn vị, NCC: định nghĩa; nhóm thay thế: lớp."}, {"kind": "order", "t": "Lô từ nhập tới dùng", "d": "<p>Sắp xếp.<\/p>", "items": ["Nhập lô, tạo bản ghi material_lot", "QC kiểm tra, đặt RELEASED hoặc HOLD", "Xuất lô lên chuyền", "Quét lô khi nạp, MES kiểm tra lớp và trạng thái", "Ghi tiêu hao vào lệnh"], "hints": ["Kiểm tra chất lượng trước khi xuất.", "Kiểm tra lớp và trạng thái lúc nạp."], "why": "Nhập → QC → xuất → quét kiểm tra → ghi tiêu hao."}]);
mesSim(document.getElementById("sim-l18"),Object.assign({id:"l18"},{kind:"db",title:"Lớp, định nghĩa, lô",show:"material_lot",
 tables:[{name:"material_class",cols:[{n:"class_id",ty:"text",pk:1},{n:"name",ty:"text",nn:1}],rows:[{class_id:"W320-RM",name:"Hạt điều W320 rang muối"},{class_id:"CAP",name:"Nắp hộp"}]},
  {name:"material",cols:[{n:"material_id",ty:"text",pk:1},{n:"class_id",ty:"text",nn:1,fk:"material_class:class_id"},{n:"name",ty:"text",nn:1},{n:"uom",ty:"text",nn:1,check:"uom in ('kg','cái','m')"}],
   rows:[{material_id:"HD-W320-RM-NCC-A",class_id:"W320-RM",name:"W320 rang muối NCC-A",uom:"kg"},{material_id:"HD-W320-RM-NCC-B",class_id:"W320-RM",name:"W320 rang muối NCC-B",uom:"kg"},{material_id:"CAP-500",class_id:"CAP",name:"Nắp 500 g",uom:"cái"}]},
  {name:"material_lot",cols:[{n:"lot_id",ty:"text",pk:1},{n:"material_id",ty:"text",nn:1,fk:"material:material_id"},{n:"qty",ty:"numeric",check:"qty >= 0"},{n:"expiry",ty:"date"},{n:"status",ty:"text",check:"status in ('OK','HOLD')"}],
   rows:[{lot_id:"LOT-1108",material_id:"HD-W320-RM-NCC-A",qty:1000,expiry:"2027-05-08",status:"OK"},{lot_id:"LOT-1109",material_id:"HD-W320-RM-NCC-A",qty:800,expiry:"2027-05-20",status:"OK"},{lot_id:"CAP-77",material_id:"CAP-500",qty:9000,expiry:"2028-01-01",status:"OK"}]}],
 sql:"SELECT l.lot_id, l.qty, m.uom, c.name AS lop\nFROM material_lot l\nJOIN material m ON m.material_id = l.material_id\nJOIN material_class c ON c.class_id = m.class_id\nWHERE c.class_id = 'W320-RM';",
 samples:[{l:"Nhập lô NCC-B",sql:"INSERT INTO material_lot VALUES ('LOT-1112', 'HD-W320-RM-NCC-B', 500, '2027-06-01', 'OK');"},{l:"Giữ lô",sql:"UPDATE material_lot SET status = 'HOLD' WHERE lot_id = 'LOT-1112';"}],
 tasks:[{t:"Chạy truy vấn: những lô nào thuộc lớp W320 rang muối?",check:(s,c)=>c.has("sql",e=>e.ok&&e.cols.includes("lop"))},
  {t:"Nhập lô LOT-1112 của nhà cung cấp B, rồi chạy lại truy vấn theo lớp.",ok:"Lô mới hiện ngay trong lớp: BOM trỏ tới lớp nên đổi nhà cung cấp không sửa BOM.",check:(s,c)=>s.rows("material_lot").some(r=>r.lot_id==="LOT-1112")&&c.has("sql",e=>e.ok&&e.rows.some(r=>r[0]==="LOT-1112"))},
  {t:"Đặt LOT-1112 sang HOLD (thuộc tính của lô, không phải của định nghĩa).",check:s=>s.rows("material_lot").some(r=>r.lot_id==="LOT-1112"&&r.status==="HOLD")},
  {t:"Thử ghi số lượng âm cho một lô.",ok:"CHECK chặn dữ liệu vô lý ngay ở CSDL.",check:(s,c)=>c.has("sql",e=>!e.ok&&/check constraint/.test(e.err))}]}));

